QUERIES = ["SELECT substr(pickup_time, 1, 2) AS pickup_hour,\n       COUNT(*) AS orders_count\nFROM orders\nWHERE status <> 'Cancelled'\nGROUP BY substr(pickup_time, 1, 2)\nORDER BY pickup_hour;", "SELECT m.name, SUM(oi.quantity) AS portions\nFROM order_items AS oi\nJOIN orders AS o ON o.id = oi.order_id\nJOIN menu AS m ON m.id = oi.menu_item_id\nWHERE o.status = 'Completed'\nGROUP BY m.id, m.name\nORDER BY portions DESC, m.name\nLIMIT 10;", "SELECT date(created_at) AS order_date,\n       SUM(total_price) AS completed_value_kzt,\n       COUNT(*) AS completed_orders\nFROM orders\nWHERE status = 'Completed'\nGROUP BY date(created_at)\nORDER BY order_date;"]
